def refresh_default_copy(apps, schema_editor):
    Template = apps.get_model("designer", "StoreEmailTemplate")
    previous = import_module("designer.migrations.0043_default_email_templates")
    old = {event: (subject, body) for event, subject, body in previous.DEFAULTS}
    for event, subject, body in NEW_TEMPLATES:
        row = Template.objects.filter(event=event).first()
        if row is None:
            Template.objects.create(event=event, subject=subject, body=body, enabled=True)
        elif (row.subject, row.body) == old.get(event):
            row.subject, row.body = subject, body
            row.save(update_fields=["subject", "body"])


